-- Local seed, loaded by `supabase db reset`.
-- Staging: run this file once by hand. `db push` does not load it.
-- Accounts are database users only: no password and no auth.identities row,
-- so they cannot sign in. Profiles come from the handle_new_user trigger.
-- Each company gets its default Lesson event type from the seed_company trigger.

begin;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (company_id, user_id) do nothing;

on conflict (company_id, teacher_id, student_id) do nothing;

commit;
